<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {EnterpriseServices,ServiceError} from '../company-services';
 type Member={id:string;kind:'human'|'agent';name:string;canRemove:boolean;role?:string};
 type Roster={companyId:string;roomId:string;revision:number;members:Member[];canManageMembers:boolean};
 type MembersApi={snapshot:(roomId:string,signal:AbortSignal)=>Promise<Roster>;remove:(roomId:string,member:{id:string;kind:'human'|'agent'},revision:number,signal:AbortSignal)=>Promise<unknown>;add?:(roomId:string,botId:string,signal:AbortSignal)=>Promise<unknown>};
 export let companyId:string;export let actorId:string;export let currentRoom:any=null;export let roomId='';export let accessSignal:AbortSignal;export let membersApi:MembersApi|null=null;export let bots:any[]=[];let addingBot='';
 const dispatch=createEventDispatcher();let service:EnterpriseServices|null=null,viewAbort=new AbortController(),room:any=null,roster:Roster|null=null,query='',error='',notice='',loading=true,busy=false,reading=false,confirmTarget:Member|null=null,tab='members';
 let mounted=false,seen='',seenSignal:AbortSignal,seenApi:MembersApi|null=null,timer:ReturnType<typeof setInterval>,detach=()=>{};
 $: effectiveRoom=roomId||currentRoom?.id||'';
 $: visible=(roster?.members||[]).filter(m=>m.name.toLowerCase().includes(query.toLowerCase()));
 function validateRoster(value:any,id=effectiveRoom):Roster{if(value?.companyId!==companyId||value.roomId!==id||!Number.isSafeInteger(value.revision)||value.revision<0||!Array.isArray(value.members)||value.members.length>2000||typeof value.canManageMembers!=='boolean')throw new ServiceError(0,'The room membership response could not be verified.');const keys=new Set();for(const m of value.members){if(typeof m.id!=='string'||!m.id||!['human','agent'].includes(m.kind)||typeof m.name!=='string'||!m.name.trim()||typeof m.canRemove!=='boolean'||keys.has(m.kind+':'+m.id))throw new ServiceError(0,'Room member identity could not be verified.');keys.add(m.kind+':'+m.id);}return {companyId,roomId:id,revision:value.revision,canManageMembers:value.canManageMembers,members:value.members.map((m:any)=>({id:m.id,kind:m.kind,name:m.name,canRemove:m.canRemove,...(typeof m.role==='string'?{role:m.role}:{})}))};}
 function clear(){service?.close();service=null;viewAbort.abort();room=null;roster=null;query='';addingBot='';confirmTarget=null;loading=false;busy=false;reading=false;}
 function fail(e:any){if(e.name==='AbortError')return;error=e.message||'Room members are unavailable.';if([401,403,404].includes(e.status)){clear();dispatch('denied',{status:e.status});}}
 async function read(current:EnterpriseServices,api:MembersApi|null,id:string){await current.authority();const data=await current.json('/api/v1/starli/companies/'+encodeURIComponent(companyId)+'/messaging/rooms/'+encodeURIComponent(id));if(data.companyId!==companyId||data.id!==id||typeof data.name!=='string'||!['channel','dm','group','work_session'].includes(data.kind)||!['public','private'].includes(data.visibility))throw new ServiceError(403,'Room access could not be verified.');let members=null;try{members=api?validateRoster(await api.snapshot(id,viewAbort.signal),id):null;}catch(e){if((e as any).status!==503)throw e;notice=(e as Error).message;}current.current();if(viewAbort.signal.aborted)throw new DOMException('View closed','AbortError');return {room:data,roster:members};}
 async function load(){const current=service,api=membersApi,id=effectiveRoom;if(!current||reading||busy)return;reading=true;error='';try{const fresh=await read(current,api,id);if(current!==service||api!==membersApi||id!==effectiveRoom)return;room=fresh.room;roster=fresh.roster;if(confirmTarget&&!roster?.members.some(m=>m.id===confirmTarget?.id&&m.kind===confirmTarget?.kind&&m.canRemove))confirmTarget=null;dispatch('loaded',{companyId,roomId:id,room,roster});}catch(e){if(current===service)fail(e);}finally{if(current===service){reading=false;loading=false;}}}
 async function addBot(){const current=service,api=membersApi,id=effectiveRoom,target=addingBot;if(!current||!api?.add||!target||busy||!bots.some(b=>b.id===target))return;busy=true;error='';try{await api.add(id,target,viewAbort.signal);if(current!==service)return;const after=await read(current,api,id);if(current!==service||id!==effectiveRoom)return;if(!after.roster?.members.some(m=>m.kind==='agent'&&m.id===target))throw new ServiceError(0,'Bot membership is unconfirmed. Refresh before retrying.');room=after.room;roster=after.roster;addingBot='';notice='Bot added to this conversation.';dispatch('changed',{companyId,roomId:id,room,roster});}catch(e){if(current===service)fail(e);}finally{if(current===service)busy=false;}}
 async function remove(){const current=service,api=membersApi,target=confirmTarget,id=effectiveRoom;if(!current||!api||!target||busy)return;busy=true;error='';notice='';try{const fresh=await read(current,api,id);if(current!==service||api!==membersApi||id!==effectiveRoom)return;const member=fresh.roster?.members.find(m=>m.id===target.id&&m.kind===target.kind);if(!fresh.roster?.canManageMembers||!member?.canRemove||member.id===actorId)throw new ServiceError(0,'You cannot remove this participant. Refresh the room membership.');await api.remove(id,{id:member.id,kind:member.kind},fresh.roster.revision,viewAbort.signal);if(current!==service)return;current.current();const after=await read(current,api,id);if(current!==service||api!==membersApi||id!==effectiveRoom)return;if(after.roster?.members.some(m=>m.id===member.id&&m.kind===member.kind))throw new ServiceError(0,'Removal is not confirmed. Refresh before trying again.');room=after.room;roster=after.roster;confirmTarget=null;notice='Participant removed.';dispatch('changed',{companyId,roomId:id,room,roster});}catch(e){if(current===service)fail(e);}finally{if(current===service)busy=false;}}
 function start(){detach();clear();seen=companyId+'|'+actorId+'|'+effectiveRoom;seenSignal=accessSignal;seenApi=membersApi;error='';notice='';loading=true;viewAbort=new AbortController();if(!effectiveRoom){loading=false;return;}service=new EnterpriseServices(companyId,actorId,accessSignal);const signal=accessSignal;const lost=()=>clear();signal.addEventListener('abort',lost,{once:true});detach=()=>signal.removeEventListener('abort',lost);if(signal.aborted){clear();return;}void load();}
 function session(e:StorageEvent){if(e.key==='token'||e.key===null){clear();dispatch('denied',{status:401});}}
 $: if(mounted&&(seen!==companyId+'|'+actorId+'|'+effectiveRoom||seenSignal!==accessSignal||seenApi!==membersApi))start();
 onMount(()=>{mounted=true;timer=setInterval(()=>{if(!document.hidden)void load();},5000);});onDestroy(()=>{mounted=false;clearInterval(timer);detach();clear();});
</script>
<svelte:window on:storage={session}/>
<section class="members-pane" aria-label="Room details"><header><div><small>{room?.kind==='channel'?'Company channel':'Conversation'}</small><h2>{room?(room.kind==='channel'?'# ':'')+room.name:'Room details'}</h2></div><button class="close" aria-label="Close room details" on:click={()=>dispatch('close')}>×</button></header><nav aria-label="Room details tabs"><button class:active={tab==='members'} on:click={()=>tab='members'}>Members{roster?' · '+roster.members.length:''}</button><button class:active={tab==='about'} on:click={()=>tab='about'}>About</button></nav>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}{#if loading}<p class="empty" role="status">Loading current room details…</p>{:else if room}{#if tab==='about'}<div class="about"><h3>Description</h3><p>{typeof room.description==='string'?room.description||'No description added.':'Description is unavailable.'}</p><h3>Visibility</h3><p>{room.visibility==='private'?'Private conversation. Access is limited to its authorized participants.':'Company channel. Access follows your current company membership.'}</p></div>{:else}{#if roster}<div class="tools"><input aria-label="Search room members" placeholder="Find a participant…" bind:value={query}/><button disabled={busy||reading} on:click={load}>Refresh</button></div><div class="add-bot">{#if membersApi?.add&&bots.some(b=>!roster?.members.some(m=>m.kind==='agent'&&m.id===b.id))}<select aria-label="Add a company bot to this conversation" bind:value={addingBot} disabled={busy}><option value="">Add a bot…</option>{#each bots.filter(b=>!roster?.members.some(m=>m.kind==='agent'&&m.id===b.id)) as b}<option value={b.id}>{b.name}</option>{/each}</select><button disabled={!addingBot||busy} on:click={addBot}>Add</button>{/if}</div><div class="member-list">{#each visible as member(member.kind+member.id)}<article><div class="identity"><span class="avatar" class:bot={member.kind==='agent'}>{member.name.slice(0,1)}</span><div><strong>{member.name}{member.id===actorId?' (you)':''}</strong><small>{member.kind==='agent'?'Company bot':member.role||'Company member'}</small></div>{#if roster.canManageMembers&&member.canRemove&&member.id!==actorId}<button class="remove" disabled={busy} on:click={()=>confirmTarget=member}>Remove</button>{/if}</div>{#if confirmTarget?.id===member.id&&confirmTarget?.kind===member.kind}<div class="confirmation"><p>Remove {member.name} from this conversation?</p><div><button disabled={busy} on:click={()=>confirmTarget=null}>Cancel</button><button class="confirm-remove" disabled={busy} on:click={remove}>{busy?'Removing…':'Remove participant'}</button></div></div>{/if}</article>{:else}<p class="empty">{query?'No matching participants.':'No participants returned by the membership service.'}</p>{/each}</div><footer>Current room membership</footer>{:else}<p class="empty">The participant roster is not available from the active room service yet.</p><button class="retry" disabled={reading} on:click={load}>Refresh room details</button>{/if}{/if}{:else}<p class="empty">Room access is unavailable.</p>{/if}</section>
<style>.members-pane{height:100%;min-width:0;display:flex;flex-direction:column;background:#fff;color:#17243f;font-size:12px;overflow:hidden}header{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:20px 22px 16px}header>div{min-width:0}header small{font-size:9px;color:#a4b0c2}h2{font-size:16px;font-weight:550;margin:5px 0 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}button,input{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}.close{font-size:22px;color:#a4b0c3;background:none;border:0}nav{display:flex;gap:22px;padding:0 22px;border-bottom:1px solid #e6ebf4}nav button{border:0;border-bottom:2px solid transparent;background:none;color:#9aa8bd;font-size:11px;padding:10px 0 13px}nav .active{color:#3466f6;border-color:#3466f6}.tools{display:flex;gap:10px;align-items:center;padding:20px 20px 10px}.tools input{border:1px solid #e6ebf4;background:#f6f8fc;border-radius:7px;padding:9px 11px;font-size:11px;min-width:0;width:100%}.tools>button,.retry{border:0;background:none;color:#91a0b7;font-size:10px;padding:5px}.member-list{padding:0 15px;overflow:auto;flex:1;min-height:0}.member-list article{padding:13px 6px;border-bottom:1px solid #f0f3f8}.identity{display:flex;align-items:center;gap:10px}.avatar{height:31px;width:31px;flex:none;border-radius:8px;background:#eef2f8;color:#94a1b7;display:grid;place-items:center;font-size:11px}.avatar.bot{border-radius:50%;background:radial-gradient(circle at 25% 25%,#daf0ff,#87a8db 60%,#a89bd1);color:white}.identity strong{font-size:12px;font-weight:500;display:block;overflow-wrap:anywhere}.identity small{font-size:9px;color:#a2aec0;display:block;margin-top:2px}.remove{margin-left:auto;border:0;background:none;color:#b28d94;font-size:10px;padding:6px}.confirmation{background:#fff8f9;border:1px solid #f2e6e8;border-radius:8px;padding:12px;margin-top:12px;font-size:11px;color:#aa7a83}.confirmation p{margin:0 0 12px;line-height:1.6}.confirmation>div{display:flex;justify-content:flex-end;gap:12px}.confirmation button{border:0;background:none;color:#a6a1b1;font-size:10px}.confirmation .confirm-remove{color:#b06e7a}.about{padding:25px 22px;overflow:auto}.about h3{font-size:11px;font-weight:550;margin:0 0 9px}.about p{font-size:11px;line-height:1.8;color:#97a4b9;margin:0 0 28px}.empty{font-size:11px;line-height:1.8;text-align:center;padding:35px 22px;color:#9facc0}.error{font-size:11px;line-height:1.7;overflow-wrap:anywhere;padding:0 22px;color:#b16b76}.notice{font-size:11px;padding:0 22px;color:#6d9984}footer{padding:13px 21px;border-top:1px solid #edf1f7;font-size:9px;color:#aab4c4}.retry{align-self:center;margin:0 0 20px}button:focus-visible,input:focus-visible{outline:2px solid #8aabff;outline-offset:3px}.add-bot{display:flex;gap:8px;margin:0 20px 10px}.add-bot select{min-width:0;flex:1;padding:8px;border:1px solid #e6ebf4;border-radius:7px;background:white;font:inherit;font-size:11px;color:#7e91ae}.add-bot button{border:0;border-radius:6px;background:#edf3ff;color:#3466f6;padding:7px 12px;font-size:11px}</style>

